verbs.source:
verb :can_be_attached_by(who) rxd {
  /* Freely attachable: mounting scheduling grants nothing by itself.
     Every verb below re-checks its own authority at call time. */
  return true;
}

verb :remind_in(delay_ms, text, tag) rxd {
  /* One-shot reminder for the CALLER. Armed `always`: a reminder whose
     room happens to be empty must still fire, which is the whole point
     of a reminder. Arming `always` needs wizard authority (CO16.6) and
     this verb is catalog-owned ($wiz), so an ordinary actor reaches it
     here and only here — that is what the gate is for. */
  if (typeof(delay_ms) != "number") { raise { code: "E_TYPE", message: "remind_in needs a delay in milliseconds", value: delay_ms }; }
  if (typeof(text) != "string" || !text) { raise { code: "E_INVARG", message: "remind_in needs a non-empty reminder", value: text }; }
  if (length(text) > 4096) { raise { code: "E_QUOTA", message: "reminder text exceeds 4096 characters", value: length(text) }; }
  /* The scheduled turn runs as `actor`, so it can do no more than the
     caller could. Passing the actor explicitly keeps the fired verb from
     having to infer who asked. */
  /* The key embeds the CALLER. Reminders used to return an opaque id that
     cancel_reminder accepted verbatim, and because this verb is $wiz-owned
     the kernel's cross-namespace check passed for anybody — one user could
     cancel another's reminder just by naming its id. Deriving the key from
     the actor means a caller can only ever address their own. */
  let label = tag;
  if (typeof(label) != "string" || !label) { label = "default"; }
  if (length(label) > 64) { raise { code: "E_INVARG", message: "reminder tag exceeds 64 characters", value: label }; }
  return schedule(this, "_deliver_reminder", [actor, text], delay_ms, { "key": "remind:" + to_string(actor) + ":" + label, "idle_policy": "always" });
}

verb :cancel_reminder(tag) rxd {
  /* Takes the TAG, never a raw schedule id. The id is rebuilt from the
     calling actor here, so there is no way to spell another user's
     reminder — which an id parameter allowed, since this verb runs with
     wizard progr and the kernel used to accept that as authority.
     Cancelling a tag that was never armed is a no-op (SC2). */
  let label = tag;
  if (typeof(label) != "string" || !label) { label = "default"; }
  cancel_schedule(to_string(this) + ":remind:" + to_string(actor) + ":" + label);
  return null;
}

verb :_deliver_reminder(who, text) rxd {
  /* Fired by the scheduler. DURABLE FIRST, then live.

     `tell` is live-only, and a scheduled turn is exactly the case where
     the actor is likely to be gone: no session, possibly not connected
     at all (SC6). A reminder that only told would vanish precisely when
     it mattered. So mint the note first — a real durable object the
     actor finds later — and only then tell, for whoever is watching. */
  if (caller != $system) { raise { code: "E_PERM", message: "_deliver_reminder is fired by the scheduler, not called", value: caller }; }
  let note = create($note, { owner: who, name: "reminder", location: who });
  note.text = text;
  note.description = "A reminder you asked for earlier.";
  tell(who, "Reminder: " + text);
  return note;
}

verb :deadline(delay_ms, verb_name, verb_args, key) rxd {
  /* Named `verb_args`, not `args`: `args` is a verb-body global (the
     current call's own argument list), so a parameter of that name does
     not compile.

     "If nothing happens by T, do X." Armed `always` because a deadline
     with nobody watching is still a deadline — that is the shape the
     escalation and auto-close patterns need.

     `verb_args` carries the SUBJECT. A deadline that could not say what it was
     about could only fire object-wide verbs, which is useless for the case
     it exists to serve ("escalate THIS task"). The first real user of this
     verb found that out immediately.

     `key` is caller-supplied and stable so the deadline can be CANCELLED
     when the thing it was waiting for happens. Re-arming the same key
     replaces rather than duplicates (CO16.2 upsert), so extending a
     deadline is just calling this again. */
  if (typeof(delay_ms) != "number") { raise { code: "E_TYPE", message: "deadline needs a delay in milliseconds", value: delay_ms }; }
  if (typeof(verb_name) != "string" || !verb_name) { raise { code: "E_INVARG", message: "deadline needs a verb name", value: verb_name }; }
  if (typeof(key) != "string" || !key) { raise { code: "E_INVARG", message: "deadline needs a stable key so it can be cancelled", value: key }; }
  let payload = verb_args;
  if (typeof(payload) != "list") { payload = []; }
  /* Internal names are not reachable this way: a deadline that could
     fire _deliver_reminder or _tick would let a caller forge the
     scheduler's own internals. */
  if (str_starts(verb_name, "_")) { raise { code: "E_PERM", message: "deadline cannot target an internal verb", value: verb_name }; }
  return schedule(this, "_fire_deadline", [verb_name, payload], delay_ms, { "key": "deadline:" + key, "idle_policy": "always" });
}

verb :cancel_deadline(key) rxd {
  /* The ack path calls this. Idempotent: cancelling a deadline that
     already fired, or was never armed, is a no-op. */
  if (typeof(key) != "string" || !key) { raise { code: "E_INVARG", message: "cancel_deadline needs the key the deadline was armed with", value: key }; }
  cancel_schedule(tostr(this) + ":deadline:" + key);
  return null;
}

verb :_fire_deadline(verb_name, verb_args) rxd {
  /* Fired by the scheduler; dispatches the caller-named verb with the
     subject it was armed with. If that verb is gone (a catalog upgrade
     renamed it, say) this raises and the failure is recorded — one visible
     failure per broken timer, which is CO16.8 working rather than silence. */
  if (caller != $system) { raise { code: "E_PERM", message: "_fire_deadline is fired by the scheduler, not called", value: caller }; }
  let payload = verb_args;
  if (typeof(payload) != "list") { payload = []; }
  return dispatch(this, verb_name, payload);
}

verb :start_ticking(rate_ms) rxd {
  /* Periodic `this:tick()`. `while_active` (the default) is deliberate:
     ambient behaviour exists to be seen, so it should not bill a world
     forever in a room nobody visits. The scope defers it while nobody is
     attached and the next accepted turn wakes it (CO16.6).

     Idempotent by construction: the stable key means calling this while
     already ticking re-arms rather than starting a second chain. The
     rate rides in the args, so the chain needs no stored state — the
     pending entry IS the state, and stopping is cancelling it. */
  if (typeof(rate_ms) != "number") { raise { code: "E_TYPE", message: "start_ticking needs a rate in milliseconds", value: rate_ms }; }
  return schedule(this, "_tick", [rate_ms], rate_ms, { "key": "tick" });
}

verb :stop_ticking() rxd {
  /* Cancels the pending entry, which is the entire state of the chain.
     A chain already stopped cancels to a no-op. */
  cancel_schedule(tostr(this) + ":tick");
  return null;
}

verb :_tick(rate_ms) rxd {
  /* One beat. Calls the consumer's own :tick, then re-arms.

     Both happen in ONE committed turn, so if :tick raises, the re-arm
     rolls back with it and the chain stops. That is the intended failure
     mode: a broken chain halts and leaves a recorded reason instead of
     failing forever every minute. */
  if (caller != $system) { raise { code: "E_PERM", message: "_tick is fired by the scheduler, not called", value: caller }; }
  let result = dispatch(this, "tick", []);
  schedule(this, "_tick", [rate_ms], rate_ms, { "key": "tick" });
  return result;
}
